});

ruleToc.nextTocUrl:
@js: result = []
id = java.get("id");
pages = java.get("page");
for (let i = 2 ; i <= pages ; i++) {
option = source.key + "/index.php?action=loadChapterPage" + "," + JSON.stringify({
  "body": `id=${id}&page=${i}`,
  "method": "POST"
});
result.push(option);
}
result;

